const A=0.5,C=2,H=0.4,W0=-2.8,B0=1.3,K=2,T=2,S=1.2,WM=4,BM=2,LIM=2/C,Q=0.7071067811865476;
const Lf=(w,b)=>0.5*(A*w*w+C*b*b);
const Y=(w,b)=>H*Lf(w,b);
const cl=(v,m)=>Math.max(-m,Math.min(m,v));
function rnd(n){const x=Math.sin(n)*43758.5453;return x-Math.floor(x);}
function nz(seed,run,k){const u=Math.max(rnd(seed*1.37+run*91.3+k*7.77+0.5),1e-9),v=rnd(seed*2.71+run*53.1+k*3.91+1.3),r=Math.sqrt(-2*Math.log(u));return [r*Math.cos(6.2832*v),r*Math.sin(6.2832*v)];}
function stepV(s,inp,seed){const B=+inp.batchSize,f=Math.sqrt((64-B)/(63*B)),n=nz(seed,s.run,s.k),lr=inp.learningRate;return [-lr*(A*s.w+S*f*n[0]),-lr*(C*s.b+S*f*n[1])];}
function fresh(w0,run,old){return {w0,run,old,w:w0,b:B0,k:0,t:0,st:0,path:[],ex:null,dv:false};}
export function initialState(){return fresh(W0,0,[]);}
function cross(w,b,d){let t=1;for(const [p,q,m] of [[w,d[0],WM],[b,d[1],BM]])if(Math.abs(p+q)>m)t=Math.min(t,((q>0?m:-m)-p)/q);return t;}
function adv(s,inp,seed){if(s.st)return s;const d=stepV(s,inp,seed),w=s.w+d[0],b=s.b+d[1],k=s.k+1,path=s.path.concat([[w,b]]).slice(-40);
if(Math.abs(w)>WM||Math.abs(b)>BM){const t=cross(s.w,s.b,d);return {...s,w,b,k,path,st:2,ex:[s.w+t*d[0],s.b+t*d[1]],dv:inp.learningRate>LIM};}
return {...s,w,b,k,path,st:k>=40?1:0};}
export function reduce({state:s,event:e,inputs,seed}){
if(e.type==='step'){if(s.st)return s;const t=s.t+1;return t%8?{...s,t}:adv({...s,t},inputs,seed);}
if(e.type==='action'){if(e.action==='oneStep')return adv(s,inputs,seed);if(e.action==='keepPath')return fresh(s.w0,s.run+1,s.path);}
if(e.type==='parameter'&&e.parameter!=='showTrueGradient')return fresh(s.w0,s.run,s.old);
if((e.type==='drag_move'||e.type==='drag_end')&&e.node==='start')return fresh(cl(e.value,3.2),s.run,s.old);
return s;}
function pt(p){if(!p||Math.abs(p[0])>WM||Math.abs(p[1])>BM)return {visible:false};return {visible:true,position:[p[0],Y(p[0],p[1])+0.06,p[1]]};}
function arr(x,y,z,d,on){const m=Math.hypot(d[0],d[1]);if(!on||m===0)return {visible:false};return {visible:true,position:[x,y,z],scale:[T,K*m,T],quaternion:[d[1]/m*Q,0,-d[0]/m*Q,Q]};}
function num(m){return m===0?'0':String(+m.toPrecision(2));}
export function evaluate({inputs,seed,state:s}){const n={},lr=inputs.learningRate,B=+inputs.batchSize,run=s.st===0,off=s.st===2;
for(let i=0;i<40;i++){n['p'+i]=pt(s.path[i]);n['o'+i]=pt(s.old[i]);}
n.start={position:[s.w0,Y(s.w0,B0)+0.04,B0]};
n.ball=off?{visible:false}:{position:[s.w,Y(s.w,s.b)+0.18,s.b]};
if(run){const y=Y(s.w,s.b)+0.18,u=stepV(s,inputs,seed),f=[-lr*A*s.w,-lr*C*s.b],mu=Math.hypot(u[0],u[1]),mf=Math.hypot(f[0],f[1]),show=inputs.showTrueGradient;
n.stepArrow=arr(s.w,y+0.22,s.b,u,true);n.trueArrow=arr(s.w,y+0.4,s.b,f,show);
n.lblStep={visible:true,text:'noisy update '+num(mu),position:[s.w+K*u[0]+0.05,y+0.1,s.b+K*u[1]]};
n.lblTrue={visible:show,text:'full-batch update '+num(mf),position:[s.w+K*f[0]+0.05,y+0.52,s.b+K*f[1]]};}
else{n.stepArrow={visible:false};n.trueArrow={visible:false};n.lblStep={visible:false};n.lblTrue={visible:false};}
n.exitM=off?{visible:true,position:[s.ex[0],Y(s.ex[0],s.ex[1])+0.06,s.ex[1]]}:{visible:false};
n.status={text:off?(s.dv?'Diverged at step '+s.k+': off plot, learning rate above '+LIM.toFixed(1):'Off plot at step '+s.k+': stopped, not proven diverged'):s.st===1?'Done: 40 steps':s.k?'Running':'Ready'};
return {nodes:n,readouts:{loss:Lf(s.w,s.b),dist:Math.hypot(s.w,s.b),stepNo:s.k,passes:s.k*B/64}};}
